/**
 * CSV parsing for the import path (REQ-1-3-1, Issue #3 decision D-A5).
 *
 * The requirement names exactly one invalid input class: a field that begins
 * with a double quote but never closes it. Everything else is accepted loosely:
 *
 * - delimiter `,`; record separators LF, CRLF and lone CR;
 * - field content is preserved verbatim (a CRLF inside a quoted field stays a
 *   CRLF, it is never normalized);
 * - only the first character of a field can open quoted mode; inside quotes
 *   `""` is one literal `"`, and `,`/newlines are literal content;
 * - text after the closing quote is appended literally (`"ab"cd` -> `abcd`);
 * - a bare `"` inside an unquoted field is a literal character;
 * - a leading UTF-8 BOM is stripped; an empty file (or BOM only) is 0 records;
 * - a trailing newline and trailing blank lines do not create a record.
 *
 * The parser is a pure function so both the import endpoint and its unit tests
 * can use it without a database.
 */

/** Invalid CSV input (the single class the requirement rejects). */
export class CsvParseError extends Error {
  constructor(message = 'Invalid CSV file format. Import failed.') {
    super(message);
    this.name = 'CsvParseError';
  }
}

/**
 * Parse CSV text into a dense array of records (`string[][]`).
 *
 * @param {string} text
 * @returns {string[][]}
 * @throws {CsvParseError} when a field opens a quote that never closes.
 */
export function parseCsv(text) {
  if (typeof text !== 'string') {
    throw new CsvParseError('CSV content must be a string');
  }

  let input = text;
  if (input.charCodeAt(0) === 0xfeff) input = input.slice(1);

  /** @type {string[][]} */
  const records = [];
  /** @type {string[]} */
  let record = [];
  let field = '';
  let quoted = false;
  /** True while no character of the current field has been consumed yet. */
  let atFieldStart = true;
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    if (quoted) {
      if (ch === '"') {
        if (input[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        quoted = false;
        i += 1;
        continue;
      }
      field += ch;
      i += 1;
      continue;
    }

    if (atFieldStart && ch === '"') {
      quoted = true;
      atFieldStart = false;
      i += 1;
      continue;
    }

    if (ch === ',') {
      record.push(field);
      field = '';
      atFieldStart = true;
      i += 1;
      continue;
    }

    if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && input[i + 1] === '\n') i += 1;
      i += 1;
      record.push(field);
      records.push(record);
      record = [];
      field = '';
      atFieldStart = true;
      continue;
    }

    field += ch;
    atFieldStart = false;
    i += 1;
  }

  if (quoted) {
    throw new CsvParseError();
  }

  // A record is still buffered when the input did not end with a separator
  // (`a,b`) or when the last character was a delimiter (`a,` -> trailing empty
  // field). An input that ended exactly on a separator leaves `atFieldStart`
  // true with nothing buffered, which produces no extra record.
  if (!atFieldStart || field !== '' || record.length > 0) {
    record.push(field);
    records.push(record);
  }

  // Trailing blank lines (`a\n\n`, `\n`) are line noise, not records; a blank
  // line is a record holding exactly one empty field.
  while (records.length > 0) {
    const last = records[records.length - 1];
    if (last.length === 1 && last[0] === '') records.pop();
    else break;
  }

  return records;
}

/**
 * Column count of a parsed CSV: the widest record. Empty input is 0 columns.
 *
 * @param {string[][]} records
 * @returns {number}
 */
export function csvColumnCount(records) {
  let cols = 0;
  for (const record of records) {
    if (record.length > cols) cols = record.length;
  }
  return cols;
}

/**
 * Derive the workbook name from the uploaded file name: drop a trailing
 * `.csv` (case-insensitive), then fall back to the backend default when
 * nothing usable remains.
 *
 * @param {string} fileName
 * @param {string} fallback
 * @returns {string}
 */
export function workbookNameFromFileName(fileName, fallback) {
  const stripped = fileName.trim().replace(/\.csv$/i, '');
  const name = stripped.trim();
  return name || fallback;
}
